#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>

int main() {
    std::string firstLine, secondLine;
    std::getline(std::cin, firstLine);
    std::getline(std::cin, secondLine);

    // Process secondLine to replace underscores with spaces and trim
    std::string processed = secondLine;
    size_t pos = 0;
    while ((pos = processed.find("_+", pos)) != std::string::npos) {
        processed.replace(pos, 2, " ");
        pos += 1;
    }
    // Remove leading and trailing spaces
    auto start = processed.find_first_not_of(' ');
    auto end = processed.find_last_not_of(' ');
    if (start == std::string::npos) {
        processed = "";
    } else {
        processed = processed.substr(start, end - start + 1);
    }

    // Extract characters inside parentheses
    std::stringstream bufferStream;
    int inside = 0;
    for (char ch : processed) {
        if (ch == '(') {
            inside = 1;
        } else if (ch == ')') {
            bufferStream << ' ';
            inside = 0;
        } else if (inside == 1) {
            bufferStream << ch;
        }
    }
    std::string bufferStr = bufferStream.str();

    // Remove all parentheses and their contents from secondLine
    std::string s = secondLine;
    size_t startPos = 0;
    while ((startPos = s.find('(')) != std::string::npos) {
        size_t endPos = s.find(')', startPos);
        if (endPos == std::string::npos) break;
        s = s.substr(0, startPos) + " " + s.substr(endPos + 1);
    }

    // Replace multiple spaces with single space and trim
    std::string temp;
    std::istringstream iss(s);
    std::string token;
    std::vector<std::string> tokens;
    while (iss >> token) {
        tokens.push_back(token);
    }
    s = "";
    for (size_t i = 0; i < tokens.size(); ++i) {
        s += tokens[i];
        if (i != tokens.size() - 1) s += " ";
    }

    // Process insideStr
    std::string insideStr = bufferStr;
    // Replace multiple spaces with single space and trim
    std::istringstream iss2(insideStr);
    std::vector<std::string> inTokens;
    while (iss2 >> token) {
        inTokens.push_back(token);
    }
    insideStr = "";
    for (size_t i = 0; i < inTokens.size(); ++i) {
        insideStr += inTokens[i];
        if (i != inTokens.size() - 1) insideStr += " ";
    }

    // Split s and insideStr into words
    std::vector<std::string> outArr, inArr;
    std::istringstream iss3(s);
    while (iss3 >> token) {
        outArr.push_back(token);
    }
    std::istringstream iss4(insideStr);
    while (iss4 >> token) {
        inArr.push_back(token);
    }

    // Find max length of words in outArr
    size_t maxLen = 0;
    for (const auto& word : outArr) {
        if (word.length() > maxLen) {
            maxLen = word.length();
        }
    }

    if (!insideStr.empty()) {
        std::cout << maxLen << " " << inArr.size() << std::endl;
    } else {
        std::cout << maxLen << " 0" << std::endl;
    }

    return 0;
}
